package net.officefloor.hq.app.patron;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The patrons each person on a sheet has named. */
@Repository
public class Patrons {

    private static final RowMapper<Patron> ROW = (rs, i) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id"));

    private final JdbcTemplate jdbc;

    public Patrons(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every patron named on the sheet. */
    public List<Patron> list(String sheet) {
        return jdbc.query("SELECT person_id, patron_id FROM patron WHERE sheet = ? ORDER BY person_id, patron_id", ROW,
                sheet);
    }

    /** Whether the person has already named this patron. */
    public boolean has(String sheet, long person, long patron) {
        Integer found = jdbc.queryForObject(
                "SELECT COUNT(*) FROM patron WHERE sheet = ? AND person_id = ? AND patron_id = ?", Integer.class, sheet,
                person, patron);
        return found != null && found > 0;
    }

    public void add(String sheet, long person, long patron) {
        jdbc.update("INSERT INTO patron (sheet, person_id, patron_id) VALUES (?, ?, ?)", sheet, person, patron);
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with every patron named on the sheet. */
public class RespondWithPatrons {
    public void respond(@PathVariable("sheet") String sheet, Patrons patrons, ObjectResponse<List<Patron>> response) {
        response.send(patrons.list(sheet));
    }
}
-- The patrons a person has named on the sheet: other people on it, each at most once.
CREATE TABLE patron (
    sheet     VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    patron_id BIGINT       NOT NULL,
    PRIMARY KEY (sheet, person_id, patron_id)
);
-- A person's contact: trimmed and lower-cased, not shared with another person on the sheet; null when they have none.
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet, name_key);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peoplePath, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { recentSettledCents, useClaims } from '../claims/claims';
import { twoDecimals } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, usePatrons } from './patrons';
import type { Patron } from './patrons';

function PatronsHeader() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

// A person's patrons (names sorted, comma separated) and their backing: the patrons' settled figures added up
// over their SETTLED claims dated within the 90 days up to and including the sheet's today (0.00 with none). A patron is picked from the others on the sheet and named one at a time; the
// server refuses a patron already named.
function PersonPatrons({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  const { data: patrons = [] } = usePatrons(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const today = useSheetToday(sheet);
  const [picked, setPicked] = useState('');

  const mine = patrons
    .filter((p) => p.person === person.id)
    .map((p) => everyone.find((e) => e.id === p.patron))
    .filter((p): p is Person => p !== undefined);
  const names = mine.map((p) => p.name).sort((a, b) => a.localeCompare(b));
  const backing = mine.reduce((sum, p) => sum + recentSettledCents(claims, p, today), 0n);
  const others = everyone.filter((p) => p.id !== person.id);

  const add = useMutation({
    mutationFn: (patron: number) =>
      postJson<Patron[]>(byUser(`${peoplePath(sheet)}/${person.id}/patrons`, user), { patron }),
    onSuccess: (updated) => {
      queryClient.setQueryData(patronsKey(sheet), updated);
      setPicked('');
    },
  });
  const send = useSubmitOnce(add);

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{twoDecimals(backing)}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={picked}
          onChange={(e) => {
            setPicked(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {others.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => send(picked === '' ? -1 : Number(picked))}
        >
          Add patron
        </button>
        {add.isError && (
          <span data-testid="person-patron-error" role="alert">
            {' '}A patron must be someone else on the sheet, not already named.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 50, Component: PatronsHeader }),
  PersonColumns.fill({ order: 50, Component: PersonPatrons }),
];
import { useQuery } from '@tanstack/react-query';
