import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A screen showing the sheet as of a date (?asOf=yyyy-MM-dd on its reads): each read of the sheet runs in a
 * transaction that first puts the sheet as it stood at the end of that date (see {@link SheetSnapshots#show}) and is
 * always rolled back, so every figure the endpoints make is made from that state, with the date for the sheet's
 * today, and nothing is ever written. Every change sent while the as-of date is set is refused (see ViewerGuard).
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 1)
public class AsOfView extends OncePerRequestFilter {

    public static final String PARAM = "asOf";

    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final SheetSnapshots snapshots;
    private final TransactionTemplate transaction;

    public AsOfView(SheetSnapshots snapshots, PlatformTransactionManager transactions) {
        this.snapshots = snapshots;
        this.transaction = new TransactionTemplate(transactions);
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});

